// `requested`: waiting for their owner to approve. `active`: both sides accept the secret.
type PeerStatus string

const (
	PeerStatusRequested PeerStatus = "requested"
	PeerStatusActive    PeerStatus = "active"
)

// AllValues returns all PeerStatus values.
func (PeerStatus) AllValues() []PeerStatus {
	return []PeerStatus{
		PeerStatusRequested,
		PeerStatusActive,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s PeerStatus) MarshalText() ([]byte, error) {
	switch s {
	case PeerStatusRequested:
		return []byte(s), nil
	case PeerStatusActive:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *PeerStatus) UnmarshalText(data []byte) error {
	switch PeerStatus(data) {
	case PeerStatusRequested:
		*s = PeerStatusRequested
		return nil
	case PeerStatusActive:
		*s = PeerStatusActive
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

